'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
function atomic(file,value){fs.mkdirSync(path.dirname(file),{recursive:true});const temp=file+'.tmp-'+crypto.randomBytes(8).toString('hex');let fd;try{fd=fs.openSync(temp,'wx',0o600);fs.writeFileSync(fd,JSON.stringify(value));fs.fsyncSync(fd);fs.closeSync(fd);fd=undefined;fs.renameSync(temp,file);}finally{if(fd!==undefined)fs.closeSync(fd);if(fs.existsSync(temp))fs.unlinkSync(temp);}}
function read(file,validate){if(fs.statSync(file).size>4194304)throw Error('Identity file too large');const data=JSON.parse(fs.readFileSync(file,'utf8'));validate(data);return data;}
function records(data){if(!data||typeof data!=='object'||Array.isArray(data))throw Error('Invalid identity records');const numbers=new Set(),unique=new Set();for(const [id,r]of Object.entries(data)){if(!id||id.length>256||['__proto__','constructor','prototype'].includes(id)||!r||!Number.isInteger(r.number)||r.number<2||r.number>65534||numbers.has(r.number))throw Error('Invalid or duplicate endpoint number');numbers.add(r.number);if(r.uniqueId!==undefined){if(typeof r.uniqueId!=='string'||!r.uniqueId||r.uniqueId.length>32||unique.has(r.uniqueId))throw Error('Invalid or duplicate unique ID');unique.add(r.uniqueId);}}}
class Registry{
 constructor(bridge){this.bridge=bridge;const dir=bridge.config.bridge.storagePath;if(!dir)throw Error('Persistent Matter storage path is required');this.file=path.join(dir,'endpoint-identities.json');this.revision=0;this.devices={};this.addQueue=Promise.resolve();this.failed=false;this.load();}
 load(){const valid=[],errors=[];let found=false;for(const file of [this.file,this.file+'.bak']){if(!fs.existsSync(file))continue;found=true;try{valid.push(read(file,d=>{if(d.version!==1||!Number.isSafeInteger(d.revision)||d.revision<0)throw Error('Invalid identity revision');records(d.devices);}));}catch(e){errors.push(e.message);}}
  if(found&&!valid.length)throw Error('Matter identity data damaged; startup stopped to preserve device assignments: '+errors.join('; '));
  this.migrating=!found&&!(this.bridge.endpointNumbersPath&&fs.existsSync(this.bridge.endpointNumbersPath));
  if(errors.length)console.warn('Matter identity primary/backup invalid; using verified remaining copy');
  if(valid.length){valid.sort((a,b)=>b.revision-a.revision);if(valid.length>1&&valid[0].revision===valid[1].revision&&JSON.stringify(valid[0].devices)!==JSON.stringify(valid[1].devices))throw Error('Conflicting Matter identity copies');this.devices=valid[0].devices;this.revision=valid[0].revision;}
  else {const legacy=this.bridge.endpointNumbersPath;if(legacy&&fs.existsSync(legacy)){const data=read(legacy,d=>{if(!d||typeof d!=='object'||Array.isArray(d))throw Error('Invalid legacy map');records(Object.fromEntries(Object.entries(d).map(([id,number])=>[id,{number}])));});this.devices=Object.fromEntries(Object.entries(data).map(([id,number])=>[id,{number}]));}}
  this.bridge.endpointNumbers=new Map(Object.entries(this.devices).map(([id,r])=>[id,r.number]));
 }
 save(){records(this.devices);const data={version:1,revision:this.revision+1,devices:this.devices};atomic(this.file+'.bak',data);this.revision=data.revision;atomic(this.file,data);}
 add(endpoint){const task=this.addQueue.then(async()=>{if(this.failed)throw Error('Matter identity write failed; reload required before adding endpoints');try{return await this.addOne(endpoint);}catch(e){this.failed=true;try{await endpoint.close?.();}catch{}throw e;}});this.addQueue=task.catch(()=>{});return task;}
 async addOne(endpoint){const id=endpoint.id;if(typeof id!=='string'||!id)throw Error('Stable endpoint ID required');const saved=this.devices[id];if(saved)endpoint.number=saved.number;else if(!this.migrating&&Object.keys(this.devices).length){endpoint.number=Math.max(1,...Object.values(this.devices).map(r=>r.number))+1;if(endpoint.number>65534)throw Error('Matter endpoint numbers exhausted');}
  await this.bridge.aggregator.add(endpoint);await this.bridge.flushEndpointNumbers?.();const number=endpoint.maybeNumber;if(!Number.isInteger(number)||number<2||(saved&&number!==saved.number))throw Error('Matter endpoint number changed unexpectedly');
  const info=endpoint.state.bridgedDeviceBasicInformation;if(saved?.uniqueId&&info?.uniqueId!==saved.uniqueId)await endpoint.set({bridgedDeviceBasicInformation:{uniqueId:saved.uniqueId}});
  const uniqueId=endpoint.state.bridgedDeviceBasicInformation?.uniqueId;const record={number,...(uniqueId?{uniqueId}:{})};const previous=this.devices[id];this.devices[id]=record;records(this.devices);if(JSON.stringify(previous)!==JSON.stringify(record))this.save();this.bridge.endpointNumbers.set(id,number);
 }
}
function restoreCcu(bridge){const dir=bridge.config.bridge.storagePath;if(!dir)return;const file=path.join(dir,'ccu-device-descriptions.json');let saved={};if(fs.existsSync(file))saved=read(file,d=>{if(!d||typeof d!=='object'||Array.isArray(d))throw Error('Invalid CCU descriptions');});const mapped=bridge.deviceMapper.getAllMappedDevices(),channels=bridge.ccuConnector.getChannels();
 for(const [address,device]of mapped){const channel=channels.get(address);if(!channel)continue;let values={...channel.paramsets?.VALUES};const source=bridge.findStateSourceChannel(address,channel.type,channels);if(source)values={...values,...channels.get(source)?.paramsets?.VALUES};saved[address]={address,type:device.hmChannelType,deviceType:device.hmDeviceType,name:device.name,room:device.room,values};}
 for(const [address,d]of Object.entries(saved)){if(mapped.has(address)||!bridge.isDeviceExposed(address))continue;if(!d||d.address!==address||typeof d.type!=='string'||typeof d.deviceType!=='string'||!d.values||typeof d.values!=='object')throw Error('Invalid cached CCU device');const name=bridge.config.devices?.names?.[address]||d.name;const device=bridge.deviceMapper.mapChannel(address,d.type,d.deviceType,name,d.values,d.room,bridge.config.devices?.tilt?.[address]);if(!device)throw Error('Cannot retain missing CCU device '+address);device.identityOffline=true;}
 atomic(file,saved);
}
async function unavailable(bridge,addresses){for(const [address]of bridge.deviceMapper.getAllMappedDevices()){if(!(addresses||[]).some(a=>address===a||address.startsWith(a+':')))continue;const device=bridge.deviceMapper.getMappedDevice(address);device.identityOffline=true;const endpoint=bridge.matterEndpoints.get(address);if(endpoint)await endpoint.set({bridgedDeviceBasicInformation:{reachable:false}});}}
function complete(bridge){if(bridge.identityRegistry.failed)throw Error('Matter identity persistence failed; publication refused');bridge.identityRegistry.migrating=false;for(const [address,exposed]of Object.entries(bridge.config.devices?.exposed||{})){const id='hm-'+address.replace(/[:.]/g,'-');if(exposed&&bridge.identityRegistry.devices[id]&&!bridge.matterEndpoints.has(address))throw Error('Known exposed CCU endpoint missing; incomplete Matter topology refused: '+address);}for(const [id,exposed]of Object.entries(bridge.config.systemVariables?.exposed||{})){if(exposed&&bridge.identityRegistry.devices['sysvar-'+id]&&!bridge.sysVarEndpoints.has(id))throw Error('Known exposed system variable missing; incomplete Matter topology refused: '+id);}}
module.exports={Registry,restoreCcu,unavailable,complete,atomic,records};
